'use strict';

/**
 * ============================================================
 * ZOKASCORE V2 — STEP 12: KNOWLEDGE QUERY VALIDATION
 * ============================================================
 *
 * PURPOSE
 * -------
 * Validate that the knowledge indexes generated by STEP 11
 * are structurally correct, mutually consistent, queryable,
 * and free from dangling references.
 *
 * INPUT
 * -----
 * data/intelligence/indexes/
 *
 * VALIDATES
 * ---------
 * 1. Index existence
 * 2. Expected populations
 * 3. Match record structure
 * 4. Team → Match references
 * 5. H2H → Match references
 * 6. Competition → Match references
 * 7. Season → Match references
 * 8. Cross-index consistency
 * 9. Duplicate references
 * 10. Canonical team integrity
 * 11. Player index integrity
 * 12. Negative queries
 *
 * IMPORTANT
 * ---------
 * - No source data is modified.
 * - This step is read-only.
 * - Any dangling or contradictory index reference is FAIL.
 * ============================================================
 */

const fs = require('fs');
const path = require('path');

const ROOT = path.join(__dirname, '..');

const INTEL_DIR = path.join(
    ROOT,
    'data',
    'intelligence'
);

const INDEX_DIR = path.join(
    INTEL_DIR,
    'indexes'
);

// ============================================================
// VERIFIED STEP 11 POPULATIONS
// ============================================================

const EXPECTED_MATCHES = 484270;
const EXPECTED_H2H_PAIRS = 54945;
const EXPECTED_TEAMS = 4562;
const EXPECTED_INDEXED_TEAMS = 4560;
const EXPECTED_PLAYERS = 50149;
const EXPECTED_COMPETITIONS = 241;
const EXPECTED_SEASONS = 155;

// ============================================================
// HELPERS
// ============================================================

function loadJson(filePath) {
    if (!fs.existsSync(filePath)) {
        throw new Error(
            `Required index not found: ${filePath}`
        );
    }

    try {
        return JSON.parse(
            fs.readFileSync(
                filePath,
                'utf8'
            )
        );
    } catch (err) {
        throw new Error(
            `Invalid JSON: ${filePath}\n${err.message}`
        );
    }
}

function isArray(value) {
    return Array.isArray(value);
}

function uniqueCount(array) {
    return new Set(array).size;
}

function hasDuplicates(array) {
    return uniqueCount(array) !== array.length;
}

// ============================================================
// MAIN
// ============================================================

async function runValidation() {

    console.log(
        '============================================================'
    );

    console.log(
        ' ZOKASCORE V2 — STEP 12: KNOWLEDGE QUERY VALIDATION'
    );

    console.log(
        '============================================================\n'
    );

    let pass = 0;
    let fail = 0;

    const failures = [];

    function assert(
        condition,
        testName
    ) {

        if (condition) {

            console.log(
                `✅ PASS: ${testName}`
            );

            pass++;

        } else {

            console.log(
                `❌ FAIL: ${testName}`
            );

            fail++;

            failures.push(
                testName
            );
        }
    }

    // ========================================================
    // 1. LOAD INDEXES
    // ========================================================

    console.log(
        '🔍 Loading canonical knowledge indexes...'
    );

    const matchIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'match_index.json'
            )
        );

    const h2hIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'h2h_index.json'
            )
        );

    const teamMatchIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'team_match_index.json'
            )
        );

    const competitionIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'competition_index.json'
            )
        );

    const seasonIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'season_index.json'
            )
        );

    const canonicalTeamIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'canonical_team_index.json'
            )
        );

    const playersIndex =
        loadJson(
            path.join(
                INDEX_DIR,
                'players_index.json'
            )
        );

    const players =
        playersIndex.players || [];

    console.log(
        `   ↳ Match index:       ${Object.keys(matchIndex).length.toLocaleString()}`
    );

    console.log(
        `   ↳ Team index:        ${Object.keys(teamMatchIndex).length.toLocaleString()}`
    );

    console.log(
        `   ↳ H2H pairs:         ${Object.keys(h2hIndex).length.toLocaleString()}`
    );

    console.log(
        `   ↳ Competitions:      ${Object.keys(competitionIndex).length.toLocaleString()}`
    );

    console.log(
        `   ↳ Seasons:           ${Object.keys(seasonIndex).length.toLocaleString()}`
    );

    console.log(
        `   ↳ Canonical teams:   ${Object.keys(canonicalTeamIndex).length.toLocaleString()}`
    );

    console.log(
        `   ↳ Players:           ${players.length.toLocaleString()}\n`
    );

    // ========================================================
    // 2. POPULATION GATES
    // ========================================================

    console.log(
        '--- INDEX POPULATION ---'
    );

    assert(
        Object.keys(matchIndex).length ===
        EXPECTED_MATCHES,
        `Match index populated (${EXPECTED_MATCHES.toLocaleString()})`
    );

    assert(
        Object.keys(h2hIndex).length ===
        EXPECTED_H2H_PAIRS,
        `H2H index populated (${EXPECTED_H2H_PAIRS.toLocaleString()})`
    );

    assert(
        Object.keys(teamMatchIndex).length ===
        EXPECTED_INDEXED_TEAMS,
        `Team match index populated (${EXPECTED_INDEXED_TEAMS.toLocaleString()})`
    );

    assert(
        Object.keys(competitionIndex).length ===
        EXPECTED_COMPETITIONS,
        `Competition index populated (${EXPECTED_COMPETITIONS})`
    );

    assert(
        Object.keys(seasonIndex).length ===
        EXPECTED_SEASONS,
        `Season index populated (${EXPECTED_SEASONS})`
    );

    assert(
        Object.keys(canonicalTeamIndex).length ===
        EXPECTED_TEAMS,
        `Canonical team index populated (${EXPECTED_TEAMS.toLocaleString()})`
    );

    assert(
        players.length ===
        EXPECTED_PLAYERS,
        `Player index populated (${EXPECTED_PLAYERS.toLocaleString()})`
    );

    // ========================================================
    // 3. MATCH RECORD STRUCTURE
    // ========================================================

    console.log(
        '\n--- MATCH RECORD STRUCTURE ---'
    );

    let malformedMatches = 0;

    for (
        const [
            matchId,
            match
        ]
        of Object.entries(
            matchIndex
        )
    ) {

        if (
            !match ||
            !match.date ||
            !match.home_team_id ||
            !match.away_team_id ||
            match.home_score === undefined ||
            match.away_score === undefined ||
            !match.competition ||
            !match.season
        ) {

            malformedMatches++;

            if (
                malformedMatches <= 5
            ) {
                console.log(
                    `   ⚠️ Malformed match: ${matchId}`
                );
            }
        }
    }

    assert(
        malformedMatches === 0,
        'All Match Index records contain required fields'
    );

    // ========================================================
    // 4. MATCH ID UNIQUENESS
    // ========================================================

    console.log(
        '\n--- MATCH ID UNIQUENESS ---'
    );

    const matchIds =
        Object.keys(
            matchIndex
        );

    assert(
        uniqueCount(matchIds) ===
        matchIds.length,
        'Match Index contains unique Match IDs'
    );

    // ========================================================
    // 5. H2H REFERENCES
    // ========================================================

    console.log(
        '\n--- H2H INDEX INTEGRITY ---'
    );

    let h2hDangling = 0;
    let h2hDuplicates = 0;
    let h2hWrongPair = 0;

    for (
        const [
            key,
            ids
        ]
        of Object.entries(
            h2hIndex
        )
    ) {

        if (!isArray(ids)) {
            h2hDangling++;
            continue;
        }

        if (hasDuplicates(ids)) {
            h2hDuplicates++;
        }

        const expectedParts =
            key.split('_vs_');

        for (
            const matchId
            of ids
        ) {

            const match =
                matchIndex[matchId];

            if (!match) {
                h2hDangling++;
                continue;
            }

            if (
                expectedParts.length === 2
            ) {

                const pair =
                    [
                        match.home_team_id,
                        match.away_team_id
                    ].sort();

                const expectedPair =
                    [
                        expectedParts[0],
                        expectedParts[1]
                    ].sort();

                if (
                    pair[0] !== expectedPair[0] ||
                    pair[1] !== expectedPair[1]
                ) {
                    h2hWrongPair++;
                }
            }
        }
    }

    assert(
        h2hDangling === 0,
        'H2H index contains no dangling Match references'
    );

    assert(
        h2hDuplicates === 0,
        'H2H index contains no duplicate Match references'
    );

    assert(
        h2hWrongPair === 0,
        'H2H keys match referenced team pairs'
    );

    // ========================================================
    // 6. TEAM → MATCH REFERENCES
    // ========================================================

    console.log(
        '\n--- TEAM MATCH INDEX INTEGRITY ---'
    );

    let teamDangling = 0;
    let teamDuplicates = 0;
    let teamWrongReference = 0;

    for (
        const [
            teamId,
            ids
        ]
        of Object.entries(
            teamMatchIndex
        )
    ) {

        if (!isArray(ids)) {
            teamDangling++;
            continue;
        }

        if (hasDuplicates(ids)) {
            teamDuplicates++;
        }

        for (
            const matchId
            of ids
        ) {

            const match =
                matchIndex[matchId];

            if (!match) {
                teamDangling++;
                continue;
            }

            if (
                match.home_team_id !== teamId &&
                match.away_team_id !== teamId
            ) {
                teamWrongReference++;
            }
        }
    }

    assert(
        teamDangling === 0,
        'Team Match Index contains no dangling Match references'
    );

    assert(
        teamDuplicates === 0,
        'Team Match Index contains no duplicate Match references'
    );

    assert(
        teamWrongReference === 0,
        'Team Match Index references only matches involving that team'
    );

    // ========================================================
    // 7. COMPETITION INDEX
    // ========================================================

    console.log(
        '\n--- COMPETITION INDEX INTEGRITY ---'
    );

    let competitionDangling = 0;
    let competitionWrong = 0;
    let competitionDuplicates = 0;

    for (
        const [
            competition,
            ids
        ]
        of Object.entries(
            competitionIndex
        )
    ) {

        if (!isArray(ids)) {
            competitionDangling++;
            continue;
        }

        if (hasDuplicates(ids)) {
            competitionDuplicates++;
        }

        for (
            const matchId
            of ids
        ) {

            const match =
                matchIndex[matchId];

            if (!match) {
                competitionDangling++;
                continue;
            }

            if (
                match.competition !==
                competition
            ) {
                competitionWrong++;
            }
        }
    }

    assert(
        competitionDangling === 0,
        'Competition index contains no dangling Match references'
    );

    assert(
        competitionDuplicates === 0,
        'Competition index contains no duplicate Match references'
    );

    assert(
        competitionWrong === 0,
        'Competition index references correct competitions'
    );

    // ========================================================
    // 8. SEASON INDEX
    // ========================================================

    console.log(
        '\n--- SEASON INDEX INTEGRITY ---'
    );

    let seasonDangling = 0;
    let seasonWrong = 0;
    let seasonDuplicates = 0;

    for (
        const [
            season,
            ids
        ]
        of Object.entries(
            seasonIndex
        )
    ) {

        if (!isArray(ids)) {
            seasonDangling++;
            continue;
        }

        if (hasDuplicates(ids)) {
            seasonDuplicates++;
        }

        for (
            const matchId
            of ids
        ) {

            const match =
                matchIndex[matchId];

            if (!match) {
                seasonDangling++;
                continue;
            }

            if (
                match.season !==
                season
            ) {
                seasonWrong++;
            }
        }
    }

    assert(
        seasonDangling === 0,
        'Season index contains no dangling Match references'
    );

    assert(
        seasonDuplicates === 0,
        'Season index contains no duplicate Match references'
    );

    assert(
        seasonWrong === 0,
        'Season index references correct seasons'
    );

    // ========================================================
    // 9. MATCH COVERAGE ACROSS INDEXES
    // ========================================================

    console.log(
        '\n--- MATCH COVERAGE ---'
    );

    let missingTeamReferences = 0;
    let missingH2HReferences = 0;
    let missingCompetitionReferences = 0;
    let missingSeasonReferences = 0;

    for (
        const matchId
        of matchIds
    ) {

        const match =
            matchIndex[matchId];

        // Team index
        const homeTeamMatches =
            teamMatchIndex[
                match.home_team_id
            ] || [];

        const awayTeamMatches =
            teamMatchIndex[
                match.away_team_id
            ] || [];

        if (
            !homeTeamMatches.includes(
                matchId
            ) ||
            !awayTeamMatches.includes(
                matchId
            )
        ) {
            missingTeamReferences++;
        }

        // H2H
        const sorted =
            [
                match.home_team_id,
                match.away_team_id
            ].sort();

        const h2hKey =
            `${sorted[0]}_vs_${sorted[1]}`;

        if (
            !(
                h2hIndex[h2hKey] ||
                []
            ).includes(matchId)
        ) {
            missingH2HReferences++;
        }

        // Competition
        if (
            !(
                competitionIndex[
                    match.competition
                ] ||
                []
            ).includes(matchId)
        ) {
            missingCompetitionReferences++;
        }

        // Season
        if (
            !(
                seasonIndex[
                    match.season
                ] ||
                []
            ).includes(matchId)
        ) {
            missingSeasonReferences++;
        }
    }

    assert(
        missingTeamReferences === 0,
        'Every Match exists in both Team Match references'
    );

    assert(
        missingH2HReferences === 0,
        'Every Match exists in its H2H index'
    );

    assert(
        missingCompetitionReferences === 0,
        'Every Match exists in its Competition index'
    );

    assert(
        missingSeasonReferences === 0,
        'Every Match exists in its Season index'
    );

    // ========================================================
    // 10. CANONICAL TEAM INDEX
    // ========================================================

    console.log(
        '\n--- CANONICAL TEAM INTEGRITY ---'
    );

    let invalidTeams = 0;

    for (
        const [
            teamId,
            team
        ]
        of Object.entries(
            canonicalTeamIndex
        )
    ) {

        if (
            !team ||
            !team.name ||
            typeof team.name !==
            'string'
        ) {
            invalidTeams++;
        }
    }

    assert(
        invalidTeams === 0,
        'Canonical team records contain valid names'
    );

    // ========================================================
    // 11. PLAYER INDEX
    // ========================================================

    console.log(
        '\n--- PLAYER INDEX INTEGRITY ---'
    );

    const playerIds =
        players.map(
            player =>
                player.player_id
        );

    const duplicatePlayers =
        playerIds.length -
        uniqueCount(playerIds);

    let invalidPlayers = 0;

    for (
        const player
        of players
    ) {

        if (
            !player ||
            !player.player_id ||
            !player.name ||
            player.total_goals === undefined ||
            player.total_appearances === undefined
        ) {
            invalidPlayers++;
        }
    }

    assert(
        duplicatePlayers === 0,
        'Player index contains unique Player IDs'
    );

    assert(
        invalidPlayers === 0,
        'Player index entries contain required fields'
    );

    // ========================================================
    // 12. QUERY TESTS
    // ========================================================

    console.log(
        '\n--- KNOWLEDGE QUERY TESTS ---'
    );

    const sampleMatchId =
        matchIds[1000];

    const sampleMatch =
        matchIndex[
            sampleMatchId
        ];

    assert(
        !!(
            sampleMatch &&
            sampleMatch.date &&
            sampleMatch.home_team_id &&
            sampleMatch.away_team_id
        ),
        'Match lookup returns complete metadata'
    );

    const h2hKeys =
        Object.keys(
            h2hIndex
        );

    const sampleH2HKey =
        h2hKeys[1000];

    const sampleH2H =
        h2hIndex[
            sampleH2HKey
        ];

    assert(
        Array.isArray(
            sampleH2H
        ) &&
        sampleH2H.length > 0,
        'H2H lookup returns Match IDs'
    );

    const teamIds =
        Object.keys(
            canonicalTeamIndex
        );

    const sampleTeamId =
        teamIds[1000];

    const sampleTeam =
        canonicalTeamIndex[
            sampleTeamId
        ];

    assert(
        !!(
            sampleTeam &&
            sampleTeam.name
        ),
        'Canonical team lookup returns team metadata'
    );

    const samplePlayer =
        players[1000];

    assert(
        !!(
            samplePlayer &&
            samplePlayer.player_id
        ),
        'Player lookup returns Player ID'
    );

    assert(
        !!(
            samplePlayer &&
            samplePlayer.name
        ),
        'Player lookup returns player name'
    );

    // ========================================================
    // 13. NEGATIVE QUERIES
    // ========================================================

    console.log(
        '\n--- NEGATIVE QUERIES ---'
    );

    assert(
        !matchIndex[
            'FAKE_MATCH_999'
        ],
        'Unknown Match ID returns no record'
    );

    assert(
        !h2hIndex[
            'FAKE_TEAM_A_vs_FAKE_TEAM_B'
        ],
        'Unknown H2H returns no record'
    );

    assert(
        !canonicalTeamIndex[
            'FAKE_TEAM_999'
        ],
        'Unknown Team ID returns no record'
    );

    // ========================================================
    // FINAL
    // ========================================================

    console.log(
        '\n============================================================'
    );

    console.log(
        ' STEP 12 VALIDATION COMPLETE'
    );

    console.log(
        '============================================================'
    );

    console.log(
        `📊 Tests Passed:  ${pass}`
    );

    console.log(
        `❌ Tests Failed: ${fail}`
    );

    if (
        failures.length > 0
    ) {

        console.log(
            '\n🔴 FAILURE SUMMARY:'
        );

        for (
            const failure
            of failures
        ) {
            console.log(
                `   - ${failure}`
            );
        }

        console.log(
            '\n🔴 KNOWLEDGE STRUCTURE: FAIL'
        );

        console.log(
            '🔒 V2 DATA WAS NOT MODIFIED.'
        );

        process.exit(1);

    } else {

        console.log(
            '\n🟢 KNOWLEDGE STRUCTURE: PASS'
        );

        console.log(
            '✅ All Step 11 knowledge indexes are internally consistent.'
        );

        console.log(
            '🔒 V2 DATA WAS NOT MODIFIED.'
        );
    }

    console.log(
        '============================================================'
    );
}

runValidation().catch(err => {

    console.error(
        '\n============================================================'
    );

    console.error(
        '❌ STEP 12 VALIDATION FAILED'
    );

    console.error(
        '============================================================'
    );

    console.error(
        err.message
    );

    console.error(
        '\n🔒 V2 DATA WAS NOT MODIFIED.'
    );

    process.exit(1);
});